def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    lines = set()

    # Join marker pairs on the opposing grid edges.
    for r in range(h):
        if grid[r][0] == 1 and grid[r][w - 1] == 1:
            for c in range(w):
                lines.add((r, c))
    for c in range(w):
        if grid[0][c] == 1 and grid[h - 1][c] == 1:
            for r in range(h):
                lines.add((r, c))

    # Objects touched by or directly adjacent to a line are changed to 1.
    near_line = set()
    for r, c in lines:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    near_line.add((rr, cc))

    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            touched = False
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                if (y, x) in near_line:
                    touched = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if touched:
                for y, x in component:
                    out[y][x] = 1

    for r, c in lines:
        out[r][c] = 1
    return out
